plugins {
    alias(conventions.plugins.javafile.java.conventions)
    alias(conventions.plugins.javafile.publishing)
}

// The arity families (call/staticCall/new_ per MethodRefN/CtorRefN, the declaration, override and body
// combinators, ...) are generated by a generator written on java-file-api-core, as java-file-api-facts's are,
// and committed under src/generated/java: each into a package-private `abstract sealed` superclass of the
// hand-written public class that inherits its forms. `generateArities` rewrites them; `checkArities` (part of
// `check`) fails when the committed sources are stale. The same generator writes the tests of the families under
// src/generatedTest/java.
val codegen = sourceSets.create("codegen")

sourceSets.main {
    java.srcDir("src/generated/java")
}

sourceSets.test {
    java.srcDir("src/generatedTest/java")
}

dependencies {
    api(project(":java-file-api-core"))
    api(project(":java-file-api-facts"))
    "codegenImplementation"(project(":java-file-api-core"))
}

testing {
    suites {
        named<JvmTestSuite>("test") {
            dependencies {
                implementation(testFixtures(project(":java-file-api-core")))
            }
        }
    }
}

val generatedDir = layout.projectDirectory.dir("src/generated/java")
val generatedTestDir = layout.projectDirectory.dir("src/generatedTest/java")

tasks {
    val generateArities = register<JavaExec>("generateArities") {
        group = "build"
        description = "Regenerates the committed arity families"
        classpath = codegen.runtimeClasspath
        mainClass = "me.supcheg.javafile.typed.codegen.TypedCodegen"
        args(generatedDir.asFile.absolutePath, generatedTestDir.asFile.absolutePath, "write")
    }

    val checkArities = register<JavaExec>("checkArities") {
        group = "verification"
        description = "Checks that the committed arity families are up to date"
        classpath = codegen.runtimeClasspath
        mainClass = "me.supcheg.javafile.typed.codegen.TypedCodegen"
        args(generatedDir.asFile.absolutePath, generatedTestDir.asFile.absolutePath, "check")
        inputs.dir(generatedDir)
        inputs.dir(generatedTestDir)
        val marker = layout.buildDirectory.file("checkArities/ok")
        outputs.file(marker)
        doLast { marker.get().asFile.writeText("ok") }
    }

    check {
        dependsOn(checkArities)
    }
}

spotless {
    java {
        targetExclude("build/**", "src/generated/**", "src/generatedTest/**")
    }
}

// The typed layer builds the metamodels of the JDK types it needs with the `@Facts` processor (Q12), and keeps them
// to itself: `-Ajavafile.facts.index=false` lists none of them for the processors of other modules. The processor
// takes `java-file-api-typed` on its own test classpath, which is no cycle: that is its tests' dependency, and the
// processor jar does not depend on the tests.
dependencies {
    annotationProcessor(project(":java-file-api-facts-processor"))
    testAnnotationProcessor(project(":java-file-api-facts-processor"))
}

tasks.compileJava {
    options.compilerArgs.addAll(
        listOf("-Ajavafile.facts.package=me.supcheg.javafile.typed.jdk.facts", "-Ajavafile.facts.index=false")
    )
}

tasks.compileTestJava {
    options.compilerArgs.addAll(
        listOf("-Ajavafile.facts.package=me.supcheg.javafile.typed.testfacts", "-Ajavafile.facts.index=false")
    )
}
